//! 🔢️ Primitive arrays retire directly under the original Source without allocating one cursor per item.
use semio_framework_value_control_contract::*;
use semio_framework_value_retirement::{self as value,retirement::RetireOwned};
use semio_framework_value_testing_effect_bank::{EffectBank,Wallet};

struct PlainArrayClose<const N:usize>(usize);
impl<const N:usize> OriginalEffectProducer for PlainArrayClose<N>{
 type Output=value::retirement::RetirementStep;type Failure=value::OriginalRetirementFailure;type Context<'a,'b>=&'a mut value::retirement::FixedArray<u8,N> where 'b:'a;
 fn validate_context<'a,'b>(&self,_:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{Ok(())}
 fn source_turn<'a,'b>(&self,_:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity>where 'b:'a{None}
 fn receive<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,e:&mut RetainedAllocationEffect<'_>,r:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{value::retirement::RetirementCursor::close_into(*c,self.0,e,r)}
 fn recover<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,e:&mut RetainedAllocationEffect<'_>,r:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{value::retirement::RetirementCursor::recover_close_into(*c,self.0,e,r)}
}
#[test]
fn primitive_fixed_array_closes_without_per_item_cursor_birth(){
 use value::retirement::{RetirementCursor,RetirementStep};let mut cursor=[7u8;8192].retirement_seed();assert_eq!(cursor.next_demand(4096).unwrap().capacity_bytes,0);let stock=RetainedCloneGrant{maximum_items:10000,maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:64};let mut bank=EffectBank::new(Wallet::new(stock,10000));let mut authority=Some(OriginalEffectAuthority::new(PlainArrayClose::<8192>(4096)));let mut turns=0;let mut items=0;
 while !cursor.terminal_is_empty(){assert!(turns<10000);let demand=cursor.next_demand(4096).unwrap();assert!(demand.copy_bytes<=4096);let grant=bank.loan(1,demand.copy_bytes);let mut action=None;let mut reply=None;let((poll,actual),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||bank.run(grant,1,|effect|{let before=effect.performed_boundary();assert!(authority.as_mut().unwrap().drive(&mut &mut cursor,effect,&mut action).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome::<(),ValueError>{result:Ok(()),work:effect.performed_since(before).unwrap()})}));assert_eq!(heap,(0,0));assert_eq!(actual,None);let RetainedWorkPoll::Complete(turn)=poll else{panic!("primitive array remained pending")};assert_eq!(turn.work,1);assert!(action.as_mut().unwrap().transfer_reply(&mut reply).unwrap());authority.as_mut().unwrap().finish(&mut action).unwrap();let step=reply.take().unwrap().unwrap();let RetirementStep::Progress(progress,work)=step else{panic!("primitive array allocated a child")};assert_eq!(work,1);assert_eq!(progress.copied_items,1);items+=progress.copied_items;assert_eq!(bank.take_admitted(),Some(true));bank.post(progress,grant,heap);turns+=1;}
 assert_eq!(items,5);assert_eq!(turns,5);let d=OriginalEffectAuthority::<PlainArrayClose<8192>>::producer_transfer_demand().unwrap();let g=bank.loan(1,d.copy_bytes);let mut producer=None;let(poll,actual)=bank.run(g,1,|effect|RetainedWorkPoll::Complete(OriginalEffectAuthority::transfer_producer(&mut authority,&&mut cursor,&mut producer,effect)));assert_eq!(actual,None);let RetainedWorkPoll::Complete(turn)=poll else{panic!("plain native authority remained pending")};assert_eq!(bank.take_admitted(),Some(true));bank.post(turn.result.unwrap().unwrap(),g,(0,0));let d=RetirementDemand{copy_bytes:std::mem::size_of_val(&producer),depth:1,..Default::default()};let g=bank.loan(1,d.copy_bytes);let(poll,actual)=bank.run(g,1,|effect|{assert!(effect.performed(1).unwrap());drop(producer.take());RetainedWorkPoll::Complete(RetainedWorkOutcome::<_,ValueError>{result:Ok(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}),work:1})});assert_eq!(actual,None);let RetainedWorkPoll::Complete(turn)=poll else{panic!("plain native producer clear remained pending")};assert_eq!(bank.take_admitted(),Some(true));bank.post(turn.result.unwrap(),g,(0,0));assert!(authority.is_none()&&producer.is_none());
}

#[test]
fn primitive_fixed_array_batches_and_denies_without_moving(){
 use value::retirement::{RetirementCursor,RetirementStep};let mut cursor=[9u8;33].retirement_seed();let stock=RetainedCloneGrant{maximum_items:100,maximum_copy_bytes:4096,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:1};let mut bank=EffectBank::new(Wallet::new(stock,10));let mut authority=Some(OriginalEffectAuthority::new(PlainArrayClose::<33>(std::mem::size_of::<usize>()+16*std::mem::size_of::<Option<u8>>())));let header=std::mem::size_of::<usize>();let slot=std::mem::size_of::<Option<u8>>();let original=cursor.next_demand(header+16*slot).unwrap();let mut counts=Vec::new();
 for (items,copy,work) in [(0,original.copy_bytes,1),(16,header+slot-1,1),(16,original.copy_bytes,0),(16,original.copy_bytes,1),(16,original.copy_bytes,1),(16,header+slot,1)]{
  let grant=RetainedCloneGrant{maximum_items:items,maximum_copy_bytes:copy,..stock};let mut action=None;let mut reply=None;let((poll,marker),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||bank.run(grant,work,|effect|{let before=effect.performed_boundary();assert!(authority.as_mut().unwrap().drive(&mut &mut cursor,effect,&mut action).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome::<(),ValueError>{result:Ok(()),work:effect.performed_since(before).unwrap()})}));assert_eq!(heap,(0,0));assert_eq!(marker,None);let RetainedWorkPoll::Complete(turn)=poll else{panic!("native discard remained pending")};assert!(action.as_mut().unwrap().transfer_reply(&mut reply).unwrap());authority.as_mut().unwrap().finish(&mut action).unwrap();let progress=match reply.take().unwrap().unwrap(){RetirementStep::BudgetExhausted=>{assert_eq!(turn.work,0);assert_eq!(cursor.next_demand(header+16*slot).unwrap(),original);RetainedCloneProgress::default()},RetirementStep::Progress(p,w)=>{assert_eq!(w,1);assert_eq!(p.copied_bytes,p.copied_items*slot+header);counts.push((p.copied_bytes-header)/slot);p},_=>panic!("native discard created a child")};assert_eq!(bank.take_admitted(),(turn.work!=0).then_some(true));bank.post(progress,grant,heap);
 }
 assert_eq!(counts,[16,16,1]);assert!(cursor.terminal_is_empty());let demand=OriginalEffectAuthority::<PlainArrayClose<33>>::producer_transfer_demand().unwrap();let grant=bank.loan(1,demand.copy_bytes);let mut producer=None;let(poll,marker)=bank.run(grant,1,|effect|RetainedWorkPoll::Complete(OriginalEffectAuthority::transfer_producer(&mut authority,&&mut cursor,&mut producer,effect)));assert_eq!(marker,None);let RetainedWorkPoll::Complete(turn)=poll else{panic!("producer handback pending")};assert_eq!(bank.take_admitted(),Some(true));bank.post(turn.result.unwrap().unwrap(),grant,(0,0));let copy=std::mem::size_of_val(&producer);let grant=bank.loan(1,copy);let(poll,marker)=bank.run(grant,1,|effect|{assert!(effect.performed(1).unwrap());drop(producer.take());RetainedWorkPoll::Complete(RetainedWorkOutcome::<_,ValueError>{result:Ok(RetainedCloneProgress{copied_items:1,copied_bytes:copy,..Default::default()}),work:1})});assert_eq!(marker,None);let RetainedWorkPoll::Complete(turn)=poll else{panic!("producer clear pending")};assert_eq!(bank.take_admitted(),Some(true));bank.post(turn.result.unwrap(),grant,(0,0));
}
